/*
 * The game's data from the user's own disc (T25, docs/port/data.md).
 *
 * The program carries no byte of the game: its initialised data (.data, .vudata, .rodata, .lit4, .sdata and the
 * tables the decompiled C takes from them) is copied at start from the disc's SLUS_200.01 into EE RAM at its PS2
 * addresses. The build knows only where (gPortDataRanges, generated by port/tools/link.py from
 * port/tools/data_layout.txt) and which words hold host addresses instead of the disc's (gPortDataFix: the game's
 * tables of function pointers, filled in by the linker, and the jump tables of library code, 0 here).
 *
 * The first run makes the data file: it finds the disc (TTT_DISC or the settings' game.disc, iso/: plat_file.c), checks
 * SLUS_200.01, IRX/RSPU2DRV.IRX and TEKKEN.BIN against the SHA-1 of the unmodified USA release (SLUS-20001), takes the
 * ranges' bytes out of the executable and writes them with a header to the data file: TTT_DATA, else ttt.dat in the
 * player's data folder (plat_paths.c; a temporary file renamed over it, so a crash leaves no half file). Later runs
 * load that file, check its SHA-1 and the disc's TEKKEN.BIN size and RSPU2DRV.IRX (which the sound driver reads at run
 * time: plat_movie.c). Any other disc is refused (exit code 4) with the reason; TTT_ALLOW_MODIFIED=1 runs it anyway and
 * marks the run "[modified game data]" (gPortModifiedData), the ground for T41's data verification. Without a disc
 * the program stops with "ttt: no disc" (exit code 2). Since T43 both wait for __wrap_main (Port_DataPending): a run
 * in real time with a window shows the setup screen instead (plat_setup.c, overlay.cpp), which checks the disc the
 * player picks and makes the data file through Port_DataInstall; `ttt --setup <disc>` does the same without a window.
 * Under TTT_SELFTEST a missing disc is not fatal (the self-tests do not run the game): EE RAM stays zero.
 *
 * The data file: "TTTDAT\0\1", then (little-endian 32-bit) header size, flags (bit 0: modified game data), payload
 * size, layout check (the payload size and SHA-1 the program expects, hashed), the payload's SHA-1, the source
 * SLUS_200.01's SHA-1; then the payload (the ranges' bytes in address order, as on the disc: the words of
 * gPortDataFix are rewritten in EE RAM after loading). It holds the user's own game data: never shipped.
 *
 * T41: the data in use is verified or not (Port_DataState). Later runs check TEKKEN.BIN's content too, not only its
 * size: its SHA-1 is kept in `<data file>.disc` with the host file's device, inode, size and modification time, and
 * while those match it is not hashed again. When they do not (a new or changed disc file), the hash runs on a thread of
 * its own (about a second, with its own file handle) while the game starts; a mismatch marks the run "[modified game
 * data]" from then on (stderr, the window title, the overlay) and the next run refuses the disc unless
 * TTT_ALLOW_MODIFIED=1. TTT_ALLOW_MODIFIED=1 alone marks nothing: only data that differs is marked. Texture
 * replacements (gs_texpack.c) are not game data and are not marked here.
 *
 * Runs in plat_mem.c's constructor, before anything of the game, or from the setup in __wrap_main before the game
 * starts: no EE stack is involved.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "port_addr.h"
#include "port_host.h"
#include "plat_lang.h"
#include "plat_os.h"

/* port/tools/link.py: build/port/gen/data_table.c */
extern const uint32_t gPortDataRanges[][2], gPortDataRangeN, gPortDataFix[][2], gPortDataFixN, gPortDataSize;
extern const uint8_t gPortDataSha1[20], gPortElfSha1[20];
extern const uint32_t gPortElfSize;

/* plat_file.c */
int Port_DiscOpen(void);
int Port_DiscUse(const char *name);
int Port_DiscBootName(const char *name, char *out, int n);
int Port_DiscArchiveReadAt(FILE *f, long long off, void *dst, size_t n);
int Port_DiscRead(uint32_t sector, uint32_t offset, void *dst, uint32_t bytes);
long Port_DiscReadFile(const char *dirName, const char *name, void *dst, long max);
long long Port_DiscArchiveSize(void);
const char *Port_DiscName(void);
const char *Port_DiscArchiveFile(long long *offset);

/* plat_paths.c, plat_settings.c */
const char *Port_DataDir(void);
void Port_MakeDirs(const char *path);
void Settings_Load(void);

int gPortModifiedData; /* 1: the run uses game data that differs from the USA release (TTT_ALLOW_MODIFIED=1) */

/* Port_DataState: what is known of the data in use (T41). */
enum { DATA_VERIFIED, DATA_MODIFIED, DATA_CHECKING, DATA_UNCHECKED };
static int sState = DATA_VERIFIED;
static char sWhy[160]; /* the first difference found, or why a check could not be made */
static pthread_mutex_t sLock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t sDone = PTHREAD_COND_INITIALIZER;

/* The other files of the unmodified USA release (SLUS-20001) the port checks; SLUS_200.01's own come from the
   layout (gPortElfSha1). Hashes only. */
static const uint8_t kRspu2Sha1[20] = {0x42, 0x31, 0xe6, 0x9b, 0xcc, 0x1b, 0x79, 0x1f, 0xa7, 0x33,
                                       0x21, 0x2b, 0x21, 0x66, 0x8d, 0x1e, 0x3c, 0xbe, 0x96, 0x68};
static const uint8_t kArchiveSha1[20] = {0x0a, 0xe3, 0x15, 0x7d, 0xa2, 0x1c, 0x92, 0xb9, 0x43, 0x41,
                                         0xef, 0x12, 0xce, 0xb9, 0xaf, 0xb2, 0x9b, 0xd2, 0xb6, 0xc0};
#define ARCHIVE_SIZE 630474752LL
#define ARCHIVE_SECTOR0 0x4820 /* plat_file.c: the archive's first table sector */
#define ELF_MAX (8u << 20)
#define IRX_MAX (1u << 20) /* also the archive's read size */

#define DAT_MAGIC "TTTDAT\0\1"
#define DAT_HEADER 64u
#define DAT_MODIFIED 1u

/* ---------------------------------------------------------------------------------------------- SHA-1 */

typedef struct {
    uint32_t h[5];
    uint64_t n;
    uint8_t buf[64];
} Sha1;

static uint32_t rol(uint32_t x, int k) { return x << k | x >> (32 - k); }

static void sha1_block(Sha1 *s, const uint8_t *p) {
    uint32_t w[80], a = s->h[0], b = s->h[1], c = s->h[2], d = s->h[3], e = s->h[4], t;
    int i;
    for (i = 0; i < 16; i++) {
        w[i] = (uint32_t)p[4 * i] << 24 | (uint32_t)p[4 * i + 1] << 16 | (uint32_t)p[4 * i + 2] << 8 | p[4 * i + 3];
    }
    for (; i < 80; i++) {
        w[i] = rol(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    }
    for (i = 0; i < 80; i++) {
        uint32_t f, k;
        if (i < 20) {
            f = (b & c) | (~b & d), k = 0x5A827999u;
        } else if (i < 40) {
            f = b ^ c ^ d, k = 0x6ED9EBA1u;
        } else if (i < 60) {
            f = (b & c) | (b & d) | (c & d), k = 0x8F1BBCDCu;
        } else {
            f = b ^ c ^ d, k = 0xCA62C1D6u;
        }
        t = rol(a, 5) + f + e + k + w[i];
        e = d, d = c, c = rol(b, 30), b = a, a = t;
    }
    s->h[0] += a, s->h[1] += b, s->h[2] += c, s->h[3] += d, s->h[4] += e;
}

static void sha1_init(Sha1 *s) {
    static const uint32_t h0[5] = {0x67452301u, 0xEFCDAB89u, 0x98BADCFEu, 0x10325476u, 0xC3D2E1F0u};
    int i;
    for (i = 0; i < 5; i++) {
        s->h[i] = h0[i];
    }
    s->n = 0;
}

static void sha1_update(Sha1 *s, const void *data, size_t len) {
    const uint8_t *p = data;
    size_t have = (size_t)(s->n & 63);
    s->n += len;
    if (have != 0) {
        size_t k = 64 - have < len ? 64 - have : len;
        memcpy(s->buf + have, p, k);
        p += k, len -= k, have += k;
        if (have < 64) {
            return;
        }
        sha1_block(s, s->buf);
    }
    for (; len >= 64; p += 64, len -= 64) {
        sha1_block(s, p);
    }
    memcpy(s->buf, p, len);
}

static void sha1_final(Sha1 *s, uint8_t out[20]) {
    uint64_t bits = s->n * 8;
    uint8_t pad[72] = {0x80};
    size_t k = (size_t)((s->n & 63) < 56 ? 56 - (s->n & 63) : 120 - (s->n & 63)), i;
    for (i = 0; i < 8; i++) {
        pad[k + i] = (uint8_t)(bits >> (56 - 8 * i));
    }
    sha1_update(s, pad, k + 8);
    for (i = 0; i < 20; i++) {
        out[i] = (uint8_t)(s->h[i / 4] >> (24 - 8 * (i % 4)));
    }
}

static void sha1(const void *p, size_t n, uint8_t out[20]) {
    Sha1 s;
    sha1_init(&s);
    sha1_update(&s, p, n);
    sha1_final(&s, out);
}

static void hex(const uint8_t h[20], char out[41]) {
    int i;
    for (i = 0; i < 20; i++) {
        snprintf(out + 2 * i, 3, "%02x", h[i]);
    }
}

/* ---------------------------------------------------------------------------------------------- helpers */

static uint32_t rd32(const uint8_t *p) { return p[0] | p[1] << 8 | p[2] << 16 | (uint32_t)p[3] << 24; }
static uint16_t rd16(const uint8_t *p) { return (uint16_t)(p[0] | p[1] << 8); }
static void wr32(uint8_t *p, uint32_t v) { p[0] = (uint8_t)v, p[1] = (uint8_t)(v >> 8), p[2] = (uint8_t)(v >> 16), p[3] = (uint8_t)(v >> 24); }

static int allow_modified(void) {
    const char *e = getenv("TTT_ALLOW_MODIFIED");
    return e != NULL && strcmp(e, "1") == 0;
}

/* The payload size and SHA-1 this program expects, folded into a word: a data file made by a build with another
   layout is made again. */
static uint32_t layout_check(void) {
    uint8_t h[20], in[24];
    memcpy(in, gPortDataSha1, 20);
    wr32(in + 20, gPortDataSize);
    sha1(in, sizeof in, h);
    return rd32(h);
}

static char sDatPath[1100];

/* The data file: TTT_DATA, else ttt.dat in the player's data folder (plat_paths.c: beside the program when it is
   portable or build/port/ttt of a checkout, else $XDG_DATA_HOME/ttt or ~/.local/share/ttt). */
static const char *dat_path(void) {
    const char *e = getenv("TTT_DATA");
    if (e != NULL && *e) {
        snprintf(sDatPath, sizeof sDatPath, "%s", e);
    } else {
        snprintf(sDatPath, sizeof sDatPath, "%s/ttt.dat", Port_DataDir());
    }
    return sDatPath;
}

/* The data file this run uses (the overlay's Game page, overlay.cpp); "" before the first look. */
const char *Port_DataPath(void) { return sDatPath; }

/* Why the game cannot start yet (T43): a missing or refused disc. The setup screen shows it (plat_setup.c), a run
   without one prints it with "ttt: " in front and exits with sPending's code. */
static char sErr[700];
/* The same reason for the setup screen in the player's language (T47): its catalog key, English text and arguments
   ({0}..), formatted when shown (the first reason is found before the language is known). */
static const char *sErrKey, *sErrEn;
static char sErrArg[4][300];
static int sPending; /* 0, 2 no disc (or none readable), 4 a refused disc; -1 the setup was asked for */

/* The setup's progress, for its screen (any thread): per mille and what is being done. */
static int sProgress;
static const char *volatile sStage = "";
/* The reason: English into sErr (stderr, `ttt --setup`), the key and the arguments kept for the screen. */
static void set_err(const char *key, const char *en, const char *a0, const char *a1, const char *a2, const char *a3) {
    const char *a[4] = {a0, a1, a2, a3};
    int i;
    for (i = 0; i < 4; i++) {
        snprintf(sErrArg[i], sizeof sErrArg[i], "%s", a[i] != NULL ? a[i] : "");
    }
    sErrKey = key;
    sErrEn = en;
    Lang_FormatEn(sErr, sizeof sErr, en, sErrArg[0], sErrArg[1], sErrArg[2], sErrArg[3], NULL);
}

/* The reason in the interface's language ("" none). */
void Port_DataErrorText(char *out, int n) {
    if (sErr[0] == 0 || sErrKey == NULL) {
        snprintf(out, (size_t)n, "%s", sErr);
        return;
    }
    Lang_Format(out, n, sErrKey, sErrEn, sErrArg[0], sErrArg[1], sErrArg[2], sErrArg[3], NULL);
}

static void progress(int permille, const char *stage) {
    sStage = stage;
    __atomic_store_n(&sProgress, permille, __ATOMIC_RELEASE);
}

void Port_DataProgress(int *permille, const char **stage) {
    *permille = __atomic_load_n(&sProgress, __ATOMIC_ACQUIRE);
    *stage = sStage;
}

static int no_disc(void) {
    set_err("data.err.no_disc", "no disc: run `ttt --setup <disc>` with your disc's folder or image (.iso, .bin, "
            ".cue), or set TTT_DISC to it (or put iso/ beside the program; last tried {0}); the game's data comes from "
            "your own disc", Port_DiscName(), NULL, NULL, NULL);
    return 2;
}

/* An unknown or modified disc: 4 with the reason in sErr, or 0 (run marked "[modified game data]") under
   TTT_ALLOW_MODIFIED=1. */
static int modified(const char *what, const uint8_t got[20], const uint8_t want[20]) {
    char g[41], w[41];
    int k;
    if (got != NULL) {
        hex(got, g);
        hex(want, w);
    }
    if (allow_modified()) {
        if (!gPortModifiedData) {
            fprintf(stderr, "ttt: [modified game data] %s differs from the USA release (TTT_ALLOW_MODIFIED=1)\n", what);
            snprintf(sWhy, sizeof sWhy, "%s", what);
        }
        gPortModifiedData = 1;
        sState = DATA_MODIFIED;
        return 0;
    }
    (void)k;
    if (got != NULL) {
        set_err("data.err.modified_sha1", "unknown or modified disc ({0}): {1} has SHA-1 {2}, expected {3}. Only the "
                "unmodified USA release of Tekken Tag Tournament (SLUS-20001) is supported; TTT_ALLOW_MODIFIED=1 runs "
                "it anyway, marked [modified game data]", Port_DiscName(), what, g, w);
    } else {
        set_err("data.err.modified", "unknown or modified disc ({0}): {1}. Only the unmodified USA release of Tekken "
                "Tag Tournament (SLUS-20001) is supported; TTT_ALLOW_MODIFIED=1 runs it anyway, marked [modified game "
                "data]", Port_DiscName(), what, NULL, NULL);
    }
    return 4;
}

static void cache_put(const uint8_t h[20]);

/* The disc's TEKKEN.BIN and RSPU2DRV.IRX, checked on every run (cheap) or with the archive's SHA-1 (full, when the
   data file is made: about a second). 0, or 4 (modified). */
static int check_disc(int full) {
    uint8_t h[20], *irx = malloc(IRX_MAX), *buf;
    long n = irx != NULL ? Port_DiscReadFile("IRX", "RSPU2DRV.IRX", irx, IRX_MAX) : -1;
    int r = 0;
    if (n < 0) {
        r = modified("IRX/RSPU2DRV.IRX is missing", NULL, NULL);
    } else {
        sha1(irx, (size_t)n, h);
        if (memcmp(h, kRspu2Sha1, 20) != 0) {
            r = modified("IRX/RSPU2DRV.IRX", h, kRspu2Sha1);
        }
    }
    free(irx);
    if (r != 0) {
        return r;
    }
    if (Port_DiscArchiveSize() != ARCHIVE_SIZE) {
        return modified("TEKKEN.BIN (size)", NULL, NULL);
    }
    if (full && (buf = malloc(IRX_MAX)) != NULL) {
        Sha1 s;
        uint32_t off;
        sha1_init(&s);
        for (off = 0; off < (uint32_t)ARCHIVE_SIZE; off += IRX_MAX) {
            uint32_t k = (uint32_t)ARCHIVE_SIZE - off < IRX_MAX ? (uint32_t)ARCHIVE_SIZE - off : IRX_MAX;
            progress(50 + (int)((long long)off * 900 / ARCHIVE_SIZE), Tr("data.stage.archive", "Checking TEKKEN.BIN"));
            if (!Port_DiscRead(ARCHIVE_SECTOR0, off, buf, k)) {
                free(buf);
                return modified("TEKKEN.BIN cannot be read", NULL, NULL);
            }
            sha1_update(&s, buf, k);
        }
        free(buf);
        sha1_final(&s, h);
        cache_put(h);
        if (memcmp(h, kArchiveSha1, 20) != 0) {
            return modified("TEKKEN.BIN", h, kArchiveSha1);
        }
    }
    return 0;
}

/* ---------------------------------------------------------------------------------------------- TEKKEN.BIN's content */

/* The host file holding TEKKEN.BIN as `<data file>.disc` keeps it: "TTTDISC 1 <device> <inode> <size> <mtime s>
   <mtime ns> <archive offset> <SHA-1 of the archive>". Numbers and a hash only. */
static int archive_key(char *key, int n) {
    long long off;
    const char *path = Port_DiscArchiveFile(&off);
    PlatOsFileKey st;
    if (path == NULL || PlatOs_FileKey(path, &st) != 0) {
        return 0;
    }
    snprintf(key, (size_t)n, "TTTDISC 1 %u:%u %llu %llu %lld %u %lld", st.dev_major, st.dev_minor, st.ino, st.size,
             st.mtime_s, st.mtime_ns, off);
    return 1;
}

static void cache_path(char *out, int n) { snprintf(out, (size_t)n, "%s.disc", sDatPath); }

static void cache_put(const uint8_t h[20]) {
    char key[200], path[1200], tmp[1300], x[41];
    FILE *f;
    int ok;
    if (!archive_key(key, sizeof key)) {
        return;
    }
    cache_path(path, sizeof path);
    snprintf(tmp, sizeof tmp, "%s.tmp-%d", path, (int)getpid());
    hex(h, x);
    Port_MakeDirs(path); /* the data file's folder, made before the data file itself */
    if ((f = fopen(tmp, "w")) == NULL) {
        return; /* checked again next time */
    }
    ok = fprintf(f, "%s %s\n", key, x) > 0;
    ok &= fclose(f) == 0;
    if (!ok || PlatOs_Replace(tmp, path) != 0) {
        unlink(tmp);
    }
}

/* 1 and the archive's SHA-1 when `<data file>.disc` holds it for the disc file as it is now. */
static int cache_get(uint8_t h[20]) {
    char key[200], path[1200], line[300];
    size_t k;
    FILE *f;
    int i, ok;
    if (!archive_key(key, sizeof key)) {
        return 0;
    }
    cache_path(path, sizeof path);
    if ((f = fopen(path, "r")) == NULL) {
        return 0;
    }
    ok = fgets(line, sizeof line, f) != NULL;
    fclose(f);
    k = strlen(key);
    if (!ok || memcmp(line, key, k) != 0 || line[k] != ' ' || strlen(line + k + 1) < 40) {
        return 0;
    }
    for (i = 0; i < 40; i++) {
        char c = line[k + 1 + i];
        int v = c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : -1;
        if (v < 0) {
            return 0;
        }
        h[i / 2] = (uint8_t)(i & 1 ? h[i / 2] | v : v << 4);
    }
    return 1;
}

/* A state found after start (the background check); a modification found first is kept. */
static void set_state(int state, const char *why) {
    pthread_mutex_lock(&sLock);
    if (sState != DATA_MODIFIED) {
        snprintf(sWhy, sizeof sWhy, "%s", why != NULL ? why : "");
        __atomic_store_n(&sState, state, __ATOMIC_RELEASE);
    }
    pthread_cond_broadcast(&sDone);
    pthread_mutex_unlock(&sLock);
}

/* The background check: the archive's SHA-1 read through a handle of its own, so the game's reads (sDisc) and their
   timing are left alone. The game never waits for it. */
static void *verify_main(void *arg) {
    uint8_t h[20], *buf = malloc(IRX_MAX);
    long long off;
    const char *path = Port_DiscArchiveFile(&off);
    FILE *f = path != NULL ? fopen(path, "rb") : NULL;
    long long at;
    int ok = f != NULL && buf != NULL;
    Sha1 s;
    (void)arg;
    sha1_init(&s);
    for (at = 0; ok && at < ARCHIVE_SIZE; at += IRX_MAX) {
        size_t k = ARCHIVE_SIZE - at < IRX_MAX ? (size_t)(ARCHIVE_SIZE - at) : IRX_MAX;
        ok = Port_DiscArchiveReadAt(f, at, buf, k);
        if (ok) {
            sha1_update(&s, buf, k);
        }
    }
    if (f != NULL) {
        fclose(f);
    }
    free(buf);
    if (!ok) {
        set_state(DATA_UNCHECKED, "TEKKEN.BIN could not be read for its check");
        return NULL;
    }
    sha1_final(&s, h);
    cache_put(h);
    if (memcmp(h, kArchiveSha1, 20) == 0) {
        set_state(DATA_VERIFIED, NULL);
    } else {
        char g[41];
        hex(h, g);
        __atomic_store_n(&gPortModifiedData, 1, __ATOMIC_RELEASE);
        fprintf(stderr, "ttt: [modified game data] TEKKEN.BIN differs from the USA release (SHA-1 %s): the run goes on "
                        "marked%s\n", g, allow_modified() ? "" : "; the next run refuses this disc unless TTT_ALLOW_MODIFIED=1");
        set_state(DATA_MODIFIED, "TEKKEN.BIN");
    }
    return NULL;
}

/* TEKKEN.BIN's content on a run that loads the data file: from `<data file>.disc` when the disc file is unchanged
   (refused if it differs, as when the data file is made), else hashed in the background. Self-tests do not hash. */
static int verify_archive(int selftest) {
    uint8_t h[20];
    pthread_t t;
    if (Port_DiscArchiveSize() != ARCHIVE_SIZE) {
        return 0; /* check_disc said so already */
    }
    if (cache_get(h)) {
        return memcmp(h, kArchiveSha1, 20) != 0 ? modified("TEKKEN.BIN", h, kArchiveSha1) : 0;
    }
    if (selftest) {
        set_state(DATA_UNCHECKED, "TEKKEN.BIN not checked (self-test)");
        return 0;
    }
    set_state(DATA_CHECKING, NULL);
    if (pthread_create(&t, NULL, verify_main, NULL) != 0) {
        set_state(DATA_UNCHECKED, "TEKKEN.BIN not checked (no thread)");
        return 0;
    }
    pthread_detach(t);
    return 0;
}

/* What is known of the data in use: 0 verified (the USA release), 1 modified ([modified game data]), 2 being checked
   (TEKKEN.BIN, in the background), 3 not checked. Any thread; also from the crash handler (a plain load). */
int Port_DataState(void) { return __atomic_load_n(&sState, __ATOMIC_ACQUIRE); }

/* The mark for titles and reports: "[modified game data]" or "". */
const char *Port_DataMark(void) { return Port_DataState() == DATA_MODIFIED ? "[modified game data]" : ""; }

/* The first difference found ("TEKKEN.BIN"...), or why the data is not checked; "" when verified. */
const char *Port_DataWhy(void) { return sWhy; }

/* The TTT_FRAMES report's line (plat_hw.c); a check still running is waited for (a second at most, once per disc). */
void Port_DataReport(void) {
    pthread_mutex_lock(&sLock);
    while (sState == DATA_CHECKING) {
        pthread_cond_wait(&sDone, &sLock);
    }
    pthread_mutex_unlock(&sLock);
    switch (Port_DataState()) {
    case DATA_VERIFIED:
        printf("ttt: data: USA release (verified)\n");
        break;
    case DATA_MODIFIED:
        printf("ttt: data: [modified game data] (%s)\n", sWhy);
        break;
    default:
        printf("ttt: data: not checked (%s)\n", sWhy[0] ? sWhy : "no disc");
        break;
    }
}

/* ---------------------------------------------------------------------------------------------- the data file */

/* Loads the data file into `payload`: 1 when it is whole, made for this layout, and (unless TTT_ALLOW_MODIFIED=1)
   of unmodified data; 0 when it should be made again. */
static int load_dat(const char *path, uint8_t *payload) {
    uint8_t hd[DAT_HEADER], h[20];
    FILE *f = fopen(path, "rb");
    int ok;
    if (f == NULL) {
        return 0;
    }
    ok = fread(hd, 1, DAT_HEADER, f) == DAT_HEADER && memcmp(hd, DAT_MAGIC, 8) == 0 && rd32(hd + 8) == DAT_HEADER &&
         rd32(hd + 16) == gPortDataSize && rd32(hd + 20) == layout_check() &&
         fread(payload, 1, gPortDataSize, f) == gPortDataSize;
    fclose(f);
    if (!ok) {
        return 0;
    }
    sha1(payload, gPortDataSize, h);
    if (memcmp(h, hd + 24, 20) != 0) {
        fprintf(stderr, "ttt: %s is damaged: making it again from the disc\n", path);
        return 0;
    }
    if ((rd32(hd + 12) & DAT_MODIFIED) || memcmp(h, gPortDataSha1, 20) != 0) {
        if (!allow_modified()) {
            return 0; /* made from a modified disc: made again (and refused, if the disc is still that one) */
        }
        modified("the data file (made from a modified SLUS_200.01)", NULL, NULL); /* allowed: marks the run */
    }
    return 1;
}

/* Writes the data file (its folder made first): 1 when written. */
static int save_dat(const char *path, const uint8_t *payload, const uint8_t elfSha1[20]) {
    char tmp[1200];
    uint8_t hd[DAT_HEADER];
    FILE *f;
    int ok;
    memset(hd, 0, sizeof hd);
    memcpy(hd, DAT_MAGIC, 8);
    wr32(hd + 8, DAT_HEADER);
    wr32(hd + 12, gPortModifiedData ? DAT_MODIFIED : 0);
    wr32(hd + 16, gPortDataSize);
    wr32(hd + 20, layout_check());
    sha1(payload, gPortDataSize, hd + 24);
    memcpy(hd + 44, elfSha1, 20);
    snprintf(tmp, sizeof tmp, "%s.tmp-%d", path, (int)getpid());
    Port_MakeDirs(path);
    f = fopen(tmp, "wb");
    if (f == NULL) {
        fprintf(stderr, "ttt: cannot write %s: the game's data is taken from the disc on every run\n", path);
        return 0;
    }
    ok = fwrite(hd, 1, DAT_HEADER, f) == DAT_HEADER && fwrite(payload, 1, gPortDataSize, f) == gPortDataSize &&
         fflush(f) == 0 && PlatOs_SyncFile(f) == 0;
    ok &= fclose(f) == 0;
    if (!ok || PlatOs_Replace(tmp, path) != 0) {
        unlink(tmp);
        fprintf(stderr, "ttt: cannot write %s: the game's data is taken from the disc on every run\n", path);
        return 0;
    }
    return 1;
}

/* The payload out of the disc's SLUS_200.01, after checking the disc: 0, or 2 (no disc) / 4 (refused) with the reason
   in sErr. */
static int extract(uint8_t *payload, uint8_t elfSha1[20]) {
    uint8_t *elf = malloc(ELF_MAX), h[20];
    char boot[64];
    long n;
    uint32_t r, at = 0, phoff, k;
    uint16_t phnum;
    int code = 0;
    if (elf == NULL) {
        fprintf(stderr, "ttt: out of memory reading the disc\n");
        exit(2);
    }
    progress(10, Tr("data.stage.elf", "Reading SLUS_200.01"));
    if (!Port_DiscOpen()) {
        free(elf);
        return no_disc();
    }
    n = Port_DiscReadFile(NULL, "SLUS_200.01", elf, ELF_MAX);
    if (n < 0) {
        if (Port_DiscBootName(Port_DiscName(), boot, sizeof boot) && strcmp(boot, "SLUS_200.01") != 0) {
            set_err("data.err.other_boot", "{0} boots {1}: it is not the USA release of Tekken Tag Tournament "
                    "(SLUS-20001), the only one supported (another region, or another game)", Port_DiscName(), boot,
                    NULL, NULL);
        } else {
            set_err("data.err.no_elf", "{0} has no SLUS_200.01: not the disc of Tekken Tag Tournament (USA, "
                    "SLUS-20001)", Port_DiscName(), NULL, NULL, NULL);
        }
        free(elf);
        return 4;
    }
    sha1(elf, (size_t)n, elfSha1);
    if ((uint32_t)n != gPortElfSize || memcmp(elfSha1, gPortElfSha1, 20) != 0) {
        code = modified("SLUS_200.01", elfSha1, gPortElfSha1);
    }
    if (code == 0 && (n < 52 || memcmp(elf, "\177ELF\001\001", 6) != 0)) {
        set_err("data.err.not_elf", "{0}: SLUS_200.01 is not a PS2 executable", Port_DiscName(), NULL, NULL, NULL);
        code = 4;
    }
    if (code == 0) {
        code = check_disc(1);
    }
    phoff = rd32(elf + 28);
    phnum = rd16(elf + 44);
    for (r = 0; code == 0 && r < gPortDataRangeN; r++) {
        uint32_t a = gPortDataRanges[r][0], size = gPortDataRanges[r][1];
        for (k = 0; k < phnum && phoff + k * 32 + 32 <= (uint32_t)n; k++) {
            const uint8_t *ph = elf + phoff + k * 32;
            uint32_t off = rd32(ph + 4), va = rd32(ph + 8), fsz = rd32(ph + 16);
            if (rd32(ph) == 1 && va <= a && a + size <= va + fsz && off + (a - va) + size <= (uint32_t)n) {
                memcpy(payload + at, elf + off + (a - va), size);
                break;
            }
        }
        if (k == phnum || phoff + k * 32 + 32 > (uint32_t)n) {
            char at8[16];
            snprintf(at8, sizeof at8, "%08X", a);
            set_err("data.err.no_range", "SLUS_200.01 has no data at 0x{0}: not the executable this program was built "
                    "for", at8, NULL, NULL, NULL);
            code = 4;
        }
        at += size;
    }
    free(elf);
    if (code != 0) {
        return code;
    }
    sha1(payload, gPortDataSize, h);
    if (memcmp(h, gPortDataSha1, 20) != 0 && !gPortModifiedData) {
        /* the right executable but other bytes: the layout does not belong to it (a build error, not the disc) */
        set_err("data.err.layout", "the data taken from SLUS_200.01 does not match port/tools/data_layout.txt", NULL,
                NULL, NULL, NULL);
        return 4;
    }
    return 0;
}

/* Functions whose PS2 address is only ever an integer in the game's data, never a pointer (R2). The split names every
 * data word equal to a function's address after that function (`.word StartThread`), and data_layout.txt lists those
 * words for the linker to fill in with the host address; for these the word is two 16-bit fields or packed bytes that
 * happen to equal the address: 0x00400000 (StartThread) is a command entry's unk4 = 0 / move 0x40 in the command lists
 * D_00482248 (24 words) and a move record's flags unk24 in D_00531EA0 (49 words, and one 0x00400100 named
 * SleepThread); the others are in D_00457380 (packed bytes), D_0044C190 (between floats), D_004EFD44 (packet words)
 * and D_00508B60. With the host address there, the forward walk 0x3F of the characters whose command list ends with
 * such an entry (Yoshimitsu among them) went on, after its 20 frames, to move 0x813 (0x0813AB70 read as two halves:
 * the move map's last record, a fall) instead of the walk loop 0x40, so the fighter fell face down after walking
 * forward. These words keep the disc's value. */
extern char StartThread[], SleepThread[], ExitThread[], iTerminateThread[], SignalSema[], WaitSema[], GsPutIMR[],
    _iWakeupThread[], DisableDispatchThread[], func_00340000[], func_003A0020[], func_00403240[];

static int never_a_pointer(uint32_t v) {
    const char *const fns[] = {StartThread,   SleepThread,    ExitThread,            iTerminateThread,
                               SignalSema,    WaitSema,       GsPutIMR,              _iWakeupThread,
                               DisableDispatchThread, func_00340000, func_003A0020, func_00403240};
    size_t i;
    for (i = 0; i < sizeof(fns) / sizeof(fns[0]); i++) {
        if (v == (uint32_t)(uintptr_t)fns[i]) {
            return 1;
        }
    }
    return 0;
}

/* The payload into EE RAM, then the words that hold host addresses. */
static void fill(const uint8_t *payload) {
    uint32_t r, at = 0;
    for (r = 0; r < gPortDataRangeN; r++) {
        memcpy(Port_Ptr(gPortDataRanges[r][0]), payload + at, gPortDataRanges[r][1]);
        at += gPortDataRanges[r][1];
    }
    for (r = 0; r < gPortDataFixN; r++) {
        uint32_t v = gPortDataFix[r][1];
        if (v != 0 && never_a_pointer(v)) {
            continue; /* an integer that equals a function's address: the disc's word stays */
        }
        memcpy(Port_Ptr(gPortDataFix[r][0]), &v, 4);
    }
}

/* The game's data into `payload`: from the data file, or from the disc (making the data file). 0, 1 (a self-test
   without a disc: no data), 2 (no disc) or 4 (a refused disc, the reason in sErr). */
static int load(const char *path, uint8_t *payload, int selftest) {
    uint8_t elfSha1[20];
    int code;
    if (load_dat(path, payload)) {
        if (Port_DiscOpen()) {
            return (code = check_disc(0)) != 0 ? code : verify_archive(selftest);
        }
        if (!selftest) {
            return no_disc();
        }
        set_state(DATA_UNCHECKED, "no disc (self-test)");
        return 0;
    }
    if (selftest && !Port_DiscOpen()) { /* a self-test without a disc: no game data */
        set_state(DATA_UNCHECKED, "no disc (self-test)");
        return 1;
    }
    if ((code = extract(payload, elfSha1)) != 0) {
        return code;
    }
    save_dat(path, payload, elfSha1);
    return 0;
}

/* The setup was asked for (plat_setup.c): `--setup` on the command line, or TTT_SETUP_TEST. Then nothing is loaded here:
   the setup checks the disc it is given. */
static int setup_asked(void) {
    const char *t = getenv("TTT_SETUP_TEST");
    if (t != NULL && *t) {
        return 1;
    }
    return PlatOs_HasArg("--setup"); /* (from a constructor: before main has its arguments) */
}

/* Fills EE RAM (already mapped) with the game's initialised data: from the data file, or from the disc (making the
   data file). plat_mem.c calls it from its constructor. When the disc is missing or refused, or the setup was asked
   for, nothing is loaded and the reason waits for __wrap_main (Port_DataPending; plat_setup.c), which shows the setup
   screen or prints it and exits. The settings are read here already: their game.disc is the disc (TTT_DISC). */
void Port_LoadGameData(void) {
    const char *path;
    const char *st = getenv("TTT_SELFTEST");
    uint8_t *payload;
    int code;
    Settings_Load();
    path = dat_path();
    if (st == NULL && setup_asked()) {
        sPending = -1;
        return;
    }
    payload = malloc(gPortDataSize);
    if (payload == NULL) {
        fprintf(stderr, "ttt: out of memory for the game's data\n");
        exit(2);
    }
    code = load(path, payload, st != NULL);
    if (code == 0) {
        fill(payload);
    } else if (code != 1 && st != NULL) {
        /* a self-test may end inside the constructors (plat_mem.c's mem): no setup, the reason and its code now */
        fflush(stdout);
        fprintf(stderr, "ttt: %s\n", sErr);
        exit(code);
    } else if (code != 1) {
        sPending = code;
    }
    free(payload);
}

/* ---------------------------------------------------------------------------------------------- the setup (T43) */

/* 0 when the game's data is in EE RAM; else why not: -1 the setup was asked for, 2 no disc, 4 a refused disc. */
int Port_DataPending(void) { return sPending; }

/* The reason for Port_DataPending, or the last setup's ("" none). */
const char *Port_DataError(void) { return sErr; }

/* The setup (plat_setup.c, on the host stack before the game starts): checks the disc at `disc`, makes the data file
   and fills EE RAM. 0, or 2 (no disc there, or the data file cannot be written) / 4 (refused) with the reason in
   Port_DataError(). */
int Port_DataInstall(const char *disc) {
    uint8_t *payload = malloc(gPortDataSize), elfSha1[20];
    char boot[64];
    int code;
    if (payload == NULL) {
        fprintf(stderr, "ttt: out of memory for the game's data\n");
        exit(2);
    }
    sErr[0] = 0;
    gPortModifiedData = 0;
    sState = DATA_VERIFIED;
    sWhy[0] = 0;
    dat_path();
    progress(0, Tr("data.stage.open", "Opening the disc"));
    if (!Port_DiscUse(disc)) {
        if (Port_DiscBootName(disc, boot, sizeof boot)) {
            set_err("data.err.no_archive", "{0} boots {1} and has no TEKKEN.BIN: it is not Tekken Tag Tournament (USA, "
                    "SLUS-20001)", disc, boot, NULL, NULL);
            code = 4;
        } else {
            set_err("data.err.no_disc_at", "no Tekken Tag Tournament disc at {0}: give the disc's folder (a mounted "
                    "disc, or its files copied) or an image of it (.iso, .bin, .cue)", disc, NULL, NULL, NULL);
            code = 2;
        }
    } else if ((code = extract(payload, elfSha1)) == 0) {
        progress(960, Tr("data.stage.write", "Writing the data file"));
        if (!save_dat(sDatPath, payload, elfSha1)) {
            set_err("data.err.cannot_write", "cannot write {0} (set TTT_DATA to a data file in a folder you can "
                    "write)", sDatPath, NULL, NULL, NULL);
            code = 2;
        } else {
            fill(payload);
            sPending = 0;
            progress(1000, Tr("data.stage.done", "Done"));
        }
    }
    free(payload);
    return code;
}
